import jsdoc from 'eslint-plugin-jsdoc'
import sonarjs from 'eslint-plugin-sonarjs'
import withNuxt from './.nuxt/eslint.config.mjs'

// Strengthened rules, taken from hortibat_frontend to keep components simple, and
// SonarCloud rules (eslint-plugin-sonarjs) checked before pushing; typed lint so the rules
// that read types (promises, `void`…) answer as in the Sonar analysis.
export default withNuxt(
  // API types generated by openapi-typescript: never edited or analysed.
  { ignores: ['app/contract/api-schema.ts'] },
  sonarjs.configs.recommended,
  {
    files: ['**/*.ts', '**/*.vue'],
    plugins: { jsdoc },
    rules: {
      // Documentation convention: every function, interface and class has a one-line description.
      'jsdoc/require-jsdoc': [
        'error',
        {
          require: { FunctionDeclaration: true, ClassDeclaration: true },
          contexts: ['TSInterfaceDeclaration', 'VariableDeclarator > ArrowFunctionExpression'],
        },
      ],
      'jsdoc/require-description': ['error', { contexts: ['any'] }],
    },
    languageOptions: {
      parserOptions: {
        // Vitest's files are in none of Nuxt's tsconfigs.
        projectService: { allowDefaultProject: ['vitest.config.ts', 'vitest.setup.ts'] },
        tsconfigRootDir: import.meta.dirname,
        extraFileExtensions: ['.vue'],
      },
    },
  },
  {
    files: ['**/*.vue'],
    rules: {
      // Aligned with Prettier, which writes `<input />` (the formatter is the reference).
      'vue/html-self-closing': ['error', { html: { void: 'always' } }],
      'vue/max-props': ['error', { maxProps: 6 }],
      'vue/max-template-depth': ['error', { maxDepth: 8 }],
      'vue/no-ref-object-reactivity-loss': 'error',
      'vue/no-unused-properties': 'error',
      'vue/no-unused-refs': 'error',
      'vue/require-typed-ref': 'error',
    },
  },
  {
    // Documentation is not required in tests.
    files: ['**/*.spec.ts', 'vitest.setup.ts'],
    rules: { 'jsdoc/require-jsdoc': 'off', 'jsdoc/require-description': 'off' },
  },
)
